def seed(apps, schema_editor):
    Exercise = apps.get_model('core', 'WorkoutExercise')
    for slug, name, movement, equipment, level, tags, instructions in CATALOG:
        Exercise.objects.update_or_create(slug=slug, defaults={
            'name': name, 'movement': movement, 'equipment': equipment,
            'minimum_level': level, 'caution_tags': tags, 'instructions': instructions, 'active': True})

class Migration(migrations.Migration):
    dependencies = [('core', '0004_workout_engine')]
    operations = [
        migrations.AddField('workoutplan', 'focus_mode', models.CharField(default='balanced', max_length=16)),
        migrations.AddField('workoutplan', 'pace', models.CharField(default='standard', max_length=16)),
        migrations.AddField('workoutsession', 'theme', models.CharField(default='full_body', max_length=16)),
        migrations.RunPython(seed, migrations.RunPython.noop),
    ]
